{
  "title": "Todo app",
  "summary": "Keep a list of tasks with a title, description, priority, due date, and mark them as done. Filter by status and edit or delete tasks.",
  "resources": [
    {
      "name": "tasks",
      "fields": [
        {"name": "title", "type": "string"},
        {"name": "description", "type": "string"},
        {"name": "priority", "type": "string", "options": ["Low", "Medium", "High"]},
        {"name": "due_date", "type": "string"},
        {"name": "done", "type": "boolean"}
      ],
      "operations": ["list", "create", "update", "delete"]
    }
  ],
  "features": [
    "Form to add a task with title, description, priority, due date, and done box",
    "List of tasks showing title, description, priority badge, due date, and done status",
    "Checkbox to mark a task as done",
    "Edit and Delete buttons on every task",
    "Filter the list by status (All, To do, In progress, Done)",
    "Sort the list by priority (Low, Medium, High)",
    "Count of tasks by status and priority on the dashboard"
  ]
}

{
  "preset": "fastapi-vanilla",
  "architecture": "A SQLite table stores tasks. A database module offers add, list, update, and delete functions. FastAPI routes under /api/tasks call them. A single HTML page lists tasks with coloured priority badges, a form to add one, and Edit and Delete buttons on each.",
  "endpoints": [
    {
      "method": "POST",
      "path": "/api/tasks",
      "summary": "Create a new task",
      "request_fields": [
        {"name": "title", "type": "string"},
        {"name": "description", "type": "string"},
        {"name": "priority", "type": "string", "options": ["Low", "Medium", "High"]},
        {"name": "due_date", "type": "string"},
        {"name": "done", "type": "boolean"}
      ],
      "response_status": 201,
      "response_fields": [
        {"name": "id", "type": "integer"},
        {"name": "title", "type": "string"},
        {"name": "description", "type": "string"},
        {"name": "priority", "type": "string", "options": ["Low", "Medium", "High"]},
        {"name": "due_date", "type": "string"},
        {"name": "done", "type": "boolean"}
      ],
      "errors": [
        {"status": 400, "detail": "Title must not be empty"}
      ],
      "examples": [
        {
          "description": "creates a new task",
          "status": 201,
          "request": {
            "title": "Buy groceries",
            "description": "Milk, eggs, bread",
            "priority": "Medium",
            "due_date": "2023-10-01",
            "done": false
          },
          "response": {
            "id": 1,
            "title": "Buy groceries",
            "description": "Milk, eggs, bread",
            "priority": "Medium",
            "due_date": "2023-10-01",
            "done": false
          }
        },
        {
          "description": "rejects an empty title",
          "status": 400,
          "request": {
            "title": "",
            "description": "Milk, eggs, bread",
            "priority": "Medium",
            "due_date": "2023-10-01",
            "done": false
          },
          "response": {"detail": "Title must not be empty"}
        }
      ]
    },
    {
      "method": "GET",
      "path": "/api/tasks",
      "summary": "List all tasks, newest first",
      "request_fields": [],
      "response_status": 200,
      "response_fields": [
        {"name": "items", "type": "array", "description": "objects with id, title, description, priority, due_date, done"}
      ],
      "errors": [],
      "examples": [
        {
          "description": "lists tasks",
          "status": 200,
          "request": {},
          "response": {}
        }
      ]
    },
    {
      "method": "PUT",
      "path": "/api/tasks/{id}",
      "summary": "Edit one task",
      "request_fields": [
        {"name": "title", "type": "string"},
        {"name": "description", "type": "string"},
        {"name": "priority", "type": "string", "options": ["Low", "Medium", "High"]},
        {"name": "due_date", "type": "string"},
        {"name": "done", "type": "boolean"}
      ],
      "response_status": 200,
      "response_fields": [
        {"name": "id", "type": "integer"},
        {"name": "title", "type": "string"},
        {"name": "description", "type": "string"},
        {"name": "priority", "type": "string", "options": ["Low", "Medium", "High"]},
        {"name": "due_date", "type": "string"},
        {"name": "done", "type": "boolean"}
      ],
      "errors": [
        {"status": 404, "detail": "Task not found"}
      ],
      "examples": [
        {
          "description": "unknown id",
          "status": 404,
          "request": {
            "id": 99999,
            "title": "Buy groceries",
            "description": "Milk, eggs, bread",
            "priority": "Medium",
            "due_date": "2023-10-01",
            "done": false
          },
          "response": {"detail": "Task not found"}
        }
      ]
    },
    {
      "method": "DELETE",
      "path": "/api/tasks/{id}",
      "summary": "Delete one task",
      "request_fields": [],
      "response_status": 200,
      "response_fields": [
        {"name": "deleted", "type": "boolean"}
      ],
      "errors": [
        {"status": 404, "detail": "Task not found"}
      ],
      "examples": [
        {
          "description": "unknown id",
          "status": 404,
          "request": {"id": 99999},
          "response": {"detail": "Task not found"}
        }
      ]
    }
  ],
  "tables": [
    {
      "name": "tasks",
      "columns": [
        {"name": "id", "type": "INTEGER", "constraints": "PRIMARY KEY AUTOINCREMENT"},
        {"name": "title", "type": "TEXT", "constraints": "NOT NULL"},
        {"name": "description", "type": "TEXT"},
        {"name": "priority", "type": "TEXT", "constraints": "NOT NULL"},
        {"name": "due_date", "type": "TEXT"},
        {"name": "done", "type": "INTEGER", "constraints": "NOT NULL DEFAULT 0"}
      ]
    }
  ],
  "db_functions": [
    {
      "name": "add_task",
      "signature": "add_task(title: str, description: str, priority: str, due_date: str, done: bool) -> dict",
      "description": "Insert and return the new row"
    },
    {
      "name": "list_tasks",
      "signature": "list_tasks() -> list[dict]",
      "description": "All rows, newest first"
    },
    {
      "name": "update_task",
      "signature": "update_task(task_id: int, title: str, description: str, priority: str, due_date: str, done: bool) -> dict | None",
      "description": "Update the row and return it, or None if the id does not exist"
    },
    {
      "name": "delete_task",
      "signature": "delete_task(task_id: int) -> bool",
      "description": "True if a row was deleted"
    }
  ],
  "ui_features": [
    "Form with title, description, priority select (Low, Medium, High), due date input, and done checkbox and a Save button",
    "List of tasks showing title, description, priority badge, due date, and done status",
    "Checkbox to mark a task as done",
    "Edit and Delete buttons on every task",
    "Filter the list by status (All, To do, In progress, Done)",
    "Sort the list by priority (Low, Medium, High)",
    "Count of tasks by status and priority on the dashboard"
  ]
}

{"thought":"Next, I'll implement the update_task function.","action":"implement","path":"database/tasks.py","content":"with connect(SCHEMA) as conn:
    cur = conn.execute("UPDATE tasks SET title = ?, description = ?, priority = ?, due_date = ?, done = ? WHERE id = ?", (title, description, priority, due_date, int(done), task_id))
    if cur.rowcount == 0:
        return None
    row = conn.execute("SELECT id, title, description, priority, due_date, done FROM tasks WHERE id = ?", (task_id,)).fetchone()
    return dict(row)","function":"update_task"}

